{
  "name": "PVI设备连接器",
  "name_en": "PVI Device Connector",
  "manufacturer": "",
  "description": "一种非物理的软件连接组件，用于通过 EPICS PVA 连接并解析 PVI 结构。它会根据类型注解自动创建设备或信号子项，在真实或模拟连接时补全并校验这些子项，供实验控制系统组织和接入基于 PVI 描述的设备对象。",
  "description_en": "A non-physical software connector used to access and interpret a PVI structure over EPICS PVA. It auto-creates device or signal children from type hints, then fills and validates them during real or mock connection so laboratory control software can assemble devices described by PVI.",
  "actions": [
    {
      "action_name": "auto-create_children_from_annotations",
      "description": "根据设备的类型注解自动创建子设备和信号占位项，便于后续由 PVI 信息补全。",
      "description_en": "Automatically create child device and signal placeholders from the device type annotations so they can later be populated from PVI data."
    },
    {
      "action_name": "auto-connect_mock",
      "description": "连接到模拟对象并为设备及其子项设置名称，用于测试或仿真环境。",
      "description_en": "Connect to a mock object and assign names to the device and its children for testing or simulation."
    },
    {
      "action_name": "auto-connect_real",
      "description": "连接真实的 PVI 结构，依据返回内容补全子项，并检查所请求的子项是否都已正确填充。",
      "description_en": "Connect to the real PVI structure, populate children from the returned information, and verify that all requested children have been filled correctly."
    }
  ],
  "tag_hints": [
    "EPICS PVA",
    "PVI structure",
    "device discovery",
    "annotation-based children",
    "signal auto-population",
    "mock connection",
    "control software integration"
  ]
}

